// HasQuizzes applies the HasEdge predicate on the "Quizzes" edge.
func HasQuizzes() predicate.Questions {
	return predicate.Questions(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, QuizzesTable, QuizzesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasQuizzesWith applies the HasEdge predicate on the "Quizzes" edge with a given conditions (other predicates).
func HasQuizzesWith(preds ...predicate.Quizzes) predicate.Questions {
	return predicate.Questions(func(s *sql.Selector) {
		step := newQuizzesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

